CREATE TABLE public.expense_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id), name text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), proposed_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.expense_categories TO authenticated;
GRANT ALL ON public.expense_categories TO service_role;
ALTER TABLE public.expense_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY category_read ON public.expense_categories FOR SELECT TO authenticated USING (company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts') AND (status='approved' OR proposed_by=auth.uid() OR public.my_role() IN ('admin','superuser')));
CREATE POLICY category_propose ON public.expense_categories FOR INSERT TO authenticated WITH CHECK (company_id=public.current_company_id() AND proposed_by=auth.uid() AND status='pending' AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts'));
CREATE POLICY category_review ON public.expense_categories FOR UPDATE TO authenticated USING (company_id=public.current_company_id() AND public.my_role() IN ('admin','superuser') AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts')) WITH CHECK (company_id=public.current_company_id());
CREATE UNIQUE INDEX expense_category_name ON public.expense_categories(company_id,lower(trim(name)));
CREATE TABLE public.expense_receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id), uploaded_by uuid NOT NULL DEFAULT auth.uid(), file_path text NOT NULL UNIQUE, page_count integer NOT NULL DEFAULT 1 CHECK (page_count>0), category_id uuid REFERENCES public.expense_categories(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.expense_receipts TO authenticated;
GRANT ALL ON public.expense_receipts TO service_role;
ALTER TABLE public.expense_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY expense_read ON public.expense_receipts FOR SELECT TO authenticated USING (company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts') AND (uploaded_by=auth.uid() OR public.my_role() IN ('admin','superuser')));
CREATE POLICY expense_capture ON public.expense_receipts FOR INSERT TO authenticated WITH CHECK (company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts') AND file_path=company_id::text||'/expenses/'||id::text||'.pdf');
CREATE POLICY expense_categorize ON public.expense_receipts FOR UPDATE TO authenticated USING (company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts') AND (uploaded_by=auth.uid() OR public.my_role() IN ('admin','superuser'))) WITH CHECK (company_id=public.current_company_id());
CREATE POLICY expense_failed_cleanup ON public.expense_receipts FOR DELETE TO authenticated USING (company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND NOT EXISTS (SELECT 1 FROM public.jobsheet_receipts r WHERE r.file_path=expense_receipts.file_path));
ALTER TABLE public.jobsheet_receipts ADD COLUMN expense_id uuid REFERENCES public.expense_receipts(id);
CREATE UNIQUE INDEX receipt_expense_attachment ON public.jobsheet_receipts(expense_id) WHERE expense_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.guard_expense_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NOT public.company_module_access(NEW.company_id,'receipts') THEN RAISE EXCEPTION 'Receipt module is unavailable'; END IF;
IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'category_id') IS DISTINCT FROM (to_jsonb(OLD)-'category_id') THEN RAISE EXCEPTION 'Receipt evidence is immutable'; END IF;
IF NEW.category_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.expense_categories c WHERE c.id=NEW.category_id AND c.company_id=NEW.company_id AND c.status='approved') THEN RAISE EXCEPTION 'Choose an approved category'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER expense_guard BEFORE INSERT OR UPDATE ON public.expense_receipts FOR EACH ROW EXECUTE FUNCTION public.guard_expense_record();
CREATE OR REPLACE FUNCTION public.guard_expense_category() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
NEW.name=trim(NEW.name); IF length(NEW.name)<1 OR length(NEW.name)>100 THEN RAISE EXCEPTION 'Category must be 1 to 100 characters'; END IF;
IF TG_OP='UPDATE' AND (NEW.id,NEW.company_id,NEW.proposed_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.proposed_by,OLD.created_at) THEN RAISE EXCEPTION 'Category identity is immutable'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER expense_category_guard BEFORE INSERT OR UPDATE ON public.expense_categories FOR EACH ROW EXECUTE FUNCTION public.guard_expense_category();
ALTER POLICY receipt_insert ON public.jobsheet_receipts WITH CHECK (company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'receipts') AND EXISTS (SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_receipts.jobsheet_id AND j.company_id=jobsheet_receipts.company_id) AND ((expense_id IS NULL AND file_path=company_id::text||'/'||jobsheet_id::text||'/'||id::text||'.pdf') OR EXISTS (SELECT 1 FROM public.expense_receipts e WHERE e.id=expense_id AND e.company_id=jobsheet_receipts.company_id AND e.file_path=jobsheet_receipts.file_path)));
ALTER POLICY receipt_file_insert ON storage.objects WITH CHECK (bucket_id='job-receipts' AND public.member_is_active(auth.uid()) AND (EXISTS (SELECT 1 FROM public.jobsheet_receipts r WHERE r.file_path=objects.name AND r.uploaded_by=auth.uid() AND public.company_module_access(r.company_id,'receipts')) OR EXISTS (SELECT 1 FROM public.expense_receipts e WHERE e.file_path=objects.name AND e.uploaded_by=auth.uid() AND public.company_module_access(e.company_id,'receipts'))));
CREATE POLICY expense_file_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='job-receipts' AND EXISTS (SELECT 1 FROM public.expense_receipts e WHERE e.file_path=objects.name));
CREATE TABLE public.jobsheet_internal_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id), jobsheet_id uuid NOT NULL REFERENCES public.job_sheets(id) ON DELETE CASCADE, author_id uuid NOT NULL DEFAULT auth.uid(), body text NOT NULL CHECK (length(trim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.jobsheet_internal_notes TO authenticated;
GRANT ALL ON public.jobsheet_internal_notes TO service_role;
ALTER TABLE public.jobsheet_internal_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_note_read ON public.jobsheet_internal_notes FOR SELECT TO authenticated USING (company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND (author_id=auth.uid() OR public.my_role() IN ('admin','superuser')) AND EXISTS (SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_id));
CREATE POLICY private_note_add ON public.jobsheet_internal_notes FOR INSERT TO authenticated WITH CHECK (company_id=public.current_company_id() AND author_id=auth.uid() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'core') AND EXISTS (SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_id AND j.company_id=jobsheet_internal_notes.company_id));
CREATE TRIGGER internal_note_commercial_guard BEFORE INSERT ON public.jobsheet_internal_notes FOR EACH ROW EXECUTE FUNCTION public.guard_parent_sheet_write();